import { DurableObject } from "cloudflare:workers";
import { pythonServer } from "../bash/commands/pyserver.js";
import { loadWorkersPyodide } from "./pyodide.js";
export class Python extends DurableObject {
    #serve = pythonServer(loadWorkersPyodide, { load: () => this.ctx.storage.get("pip"), save: installs => this.ctx.storage.put("pip", installs) });
    run(request) {
        return this.#serve(request);
    }
}
